// Site-wide default social sharing image (og:image / twitter:image and the
// LocalBusiness image). The old Cloudinary "superheroes saving data" picture
// was retired on 16 October 2026 (Sam's decision); every default now points at
// the branded card generated by scripts/generate-social-card.mjs and served
// from this origin. Pages with a genuine page-specific image (team portraits,
// blog hero images, the careers card) still pass their own.
export const DEFAULT_SOCIAL_IMAGE = 'https://fresh-tech.uk/images/fresh-tech-social-20261016.png';

// Retired URL, kept only so retained React baselines captured before the
// change can be compared after documented substitution.
export const RETIRED_SOCIAL_IMAGE = 'https://res.cloudinary.com/djkmeg5se/image/upload/w_1200,h_630,c_fill,f_auto,q_auto/fresh-tech-superheroes-saving-data.webp';

// Substitute the retired default inside a retained fixture's serialised JSON.
// Only the exact 1200x630 social crop is replaced; nothing else is rewritten.
export const replaceRetiredSocialImage = text => text.split(RETIRED_SOCIAL_IMAGE).join(DEFAULT_SOCIAL_IMAGE);
